CREATE OR REPLACE FUNCTION public.is_generic_domestic_chicken(p_name text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT lower(regexp_replace(btrim(coalesce(p_name,'')), '\s+', ' ', 'g')) ~ '^(poule|coq)( domestiques?)?( et (poule|coq)( domestiques?)?)?$' $$;
CREATE OR REPLACE FUNCTION public.guard_domestic_chicken_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='animals' THEN IF public.is_generic_domestic_chicken(NEW.name) THEN RAISE EXCEPTION 'DOMESTIC_BREED_REQUIRED: une race de poule identifiable est requise.' USING ERRCODE='23514'; END IF; ELSE IF NEW.status='approved' AND public.is_generic_domestic_chicken(NEW.animal_name) AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status OR OLD.animal_name IS DISTINCT FROM NEW.animal_name OR OLD.scientific_name IS DISTINCT FROM NEW.scientific_name) THEN RAISE EXCEPTION 'DOMESTIC_BREED_REQUIRED: préciser la race ou conserver la capture en modération.' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zzzz_guard_domestic_chicken_identity BEFORE INSERT OR UPDATE ON public.animals FOR EACH ROW EXECUTE FUNCTION public.guard_domestic_chicken_identity();
CREATE TRIGGER zzzz_guard_domestic_chicken_identity BEFORE INSERT OR UPDATE ON public.captures FOR EACH ROW EXECUTE FUNCTION public.guard_domestic_chicken_identity();